window.GAOKAO_PAPERS=window.GAOKAO_PAPERS||{};window.GAOKAO_PAPERS["2024-shanghai"]=[{"id":"2024-shanghai-q01","paperId":"2024-shanghai","number":1,"type":"fill","score":4,"lessonIds":["1.3"],"difficulty":"基础","hint":"补集就是全集里剩下、但A里没有的数。","legacy":false,"legacyReason":"","searchText":"设全集 U=\\{1,2,3,4,5\\} ，集合 A=\\{2,4\\} ，则 \\bar{A}= ________ . ","questionHtml":"设全集 <span class=\"gk-math\" data-tex=\"U=\\{1,2,3,4,5\\}\">U=\\{1,2,3,4,5\\}</span>，集合 <span class=\"gk-math\" data-tex=\"A=\\{2,4\\}\">A=\\{2,4\\}</span>，则 <span class=\"gk-math\" data-tex=\"\\bar{A}=\">\\bar{A}=</span><span class=\"gk-blank\" aria-label=\"填空\">________</span>.","optionsHtml":[],"answerHtml":"<span class=\"gk-math\" data-tex=\"\\{1,3,5\\}\">\\{1,3,5\\}</span>","answerKey":"","solutionHtml":"由题设，<span class=\"gk-math\" data-tex=\"A\">A</span> 在全集 <span class=\"gk-math\" data-tex=\"U\">U</span> 中的补集为 <span class=\"gk-math\" data-tex=\"\\bar{A}=\\{1,3,5\\}\">\\bar{A}=\\{1,3,5\\}</span>. 故答案为 <span class=\"gk-math\" data-tex=\"\\{1,3,5\\}\">\\{1,3,5\\}</span>.","sourceNote":"","specialNote":"","answerAlternatives":[]},{"id":"2024-shanghai-q02","paperId":"2024-shanghai","number":2,"type":"fill","score":4,"lessonIds":["3.1"],"difficulty":"基础","hint":"先判断3落在哪个分段，再代入对应的表达式。","legacy":false,"legacyReason":"","searchText":"已知 f(x)=\\begin{cases} \\sqrt{x}, & x>0,\\\\ 1, & x\\le 0, \\end{cases} 则 f(3)= ________ . ","questionHtml":"已知 <span class=\"gk-math\" data-tex=\"f(x)=\\begin{cases}\n\\sqrt{x}, &amp; x&gt;0,\\\\\n1, &amp; x\\le 0,\n\\end{cases}\">f(x)=\\begin{cases}\n\\sqrt{x}, &amp; x&gt;0,\\\\\n1, &amp; x\\le 0,\n\\end{cases}</span> 则 <span class=\"gk-math\" data-tex=\"f(3)=\">f(3)=</span><span class=\"gk-blank\" aria-label=\"填空\">________</span>.","optionsHtml":[],"answerHtml":"<span class=\"gk-math\" data-tex=\"\\sqrt{3}\">\\sqrt{3}</span>","answerKey":"","solutionHtml":"因为 <span class=\"gk-math\" data-tex=\"3&gt;0\">3&gt;0</span>，所以 <span class=\"gk-math\" data-tex=\"f(3)=\\sqrt{3}\">f(3)=\\sqrt{3}</span>. 故答案为 <span class=\"gk-math\" data-tex=\"\\sqrt{3}\">\\sqrt{3}</span>.","sourceNote":"","specialNote":"","answerAlternatives":[]},{"id":"2024-shanghai-q03","paperId":"2024-shanghai","number":3,"type":"fill","score":4,"lessonIds":["2.3"],"difficulty":"基础","hint":"把x²−2x−3分解成(x−3)(x+1)，看哪一段乘积为负。","legacy":false,"legacyReason":"","searchText":"已知 x\\in \\R ，则不等式 x^2-2x-3<0 的解集为 ________ . ","questionHtml":"已知 <span class=\"gk-math\" data-tex=\"x\\in \\R\">x\\in \\R</span>，则不等式 <span class=\"gk-math\" data-tex=\"x^2-2x-3&lt;0\">x^2-2x-3&lt;0</span> 的解集为<span class=\"gk-blank\" aria-label=\"填空\">________</span>.","optionsHtml":[],"answerHtml":"<span class=\"gk-math\" data-tex=\"\\{x\\mid -1&lt;x&lt;3\\}\">\\{x\\mid -1&lt;x&lt;3\\}</span>","answerKey":"","solutionHtml":"方程 <span class=\"gk-math\" data-tex=\"x^2-2x-3=0\">x^2-2x-3=0</span> 的两根为 <span class=\"gk-math\" data-tex=\"-1\">-1</span> 与 3，因此不等式 <span class=\"gk-math\" data-tex=\"x^2-2x-3&lt;0\">x^2-2x-3&lt;0</span> 的解集为 <span class=\"gk-math\" data-tex=\"\\{x\\mid -1&lt;x&lt;3\\}\">\\{x\\mid -1&lt;x&lt;3\\}</span>.","sourceNote":"","specialNote":"","answerAlternatives":[]},{"id":"2024-shanghai-q04","paperId":"2024-shanghai","number":4,"type":"fill","score":4,"lessonIds":["3.2"],"difficulty":"基础","hint":"奇函数在0处的值必须是0，先代x=0。","legacy":false,"legacyReason":"","searchText":"已知 f(x)=x^3+a ， x\\in \\R ，且 f(x) 是奇函数，则 a= ________ . ","questionHtml":"已知 <span class=\"gk-math\" data-tex=\"f(x)=x^3+a\">f(x)=x^3+a</span>，<span class=\"gk-math\" data-tex=\"x\\in \\R\">x\\in \\R</span>，且 <span class=\"gk-math\" data-tex=\"f(x)\">f(x)</span> 是奇函数，则 <span class=\"gk-math\" data-tex=\"a=\">a=</span><span class=\"gk-blank\" aria-label=\"填空\">________</span>.","optionsHtml":[],"answerHtml":"0","answerKey":"","solutionHtml":"因为 <span class=\"gk-math\" data-tex=\"f(x)\">f(x)</span> 为奇函数，所以 <span class=\"gk-math\" data-tex=\"f(-x)+f(x)=0\">f(-x)+f(x)=0</span>. 即 <span class=\"gk-math\" data-tex=\"(-x)^3+a+x^3+a=0\">(-x)^3+a+x^3+a=0</span>， 解得 <span class=\"gk-math\" data-tex=\"a=0\">a=0</span>.","sourceNote":"","specialNote":"","answerAlternatives":[]},{"id":"2024-shanghai-q05","paperId":"2024-shanghai","number":5,"type":"fill","score":4,"lessonIds":["6.3"],"difficulty":"基础","hint":"平行向量的坐标成比例，先比较2与6的倍数。","legacy":false,"legacyReason":"","searchText":"已知 k\\in \\R ， \\bs{a}=(2,5) ， \\bs{b}=(6,k) ，且 \\bs{a}\\parallel\\bs{b} ，则 k= ________ . ","questionHtml":"已知 <span class=\"gk-math\" data-tex=\"k\\in \\R\">k\\in \\R</span>，<span class=\"gk-math\" data-tex=\"\\bs{a}=(2,5)\">\\bs{a}=(2,5)</span>，<span class=\"gk-math\" data-tex=\"\\bs{b}=(6,k)\">\\bs{b}=(6,k)</span>，且 <span class=\"gk-math\" data-tex=\"\\bs{a}\\parallel\\bs{b}\">\\bs{a}\\parallel\\bs{b}</span>，则 <span class=\"gk-math\" data-tex=\"k=\">k=</span><span class=\"gk-blank\" aria-label=\"填空\">________</span>.","optionsHtml":[],"answerHtml":"15","answerKey":"","solutionHtml":"因为 <span class=\"gk-math\" data-tex=\"\\bs{a}\\parallel\\bs{b}\">\\bs{a}\\parallel\\bs{b}</span>，所以对应坐标成比例，即 <span class=\"gk-math\" data-tex=\"2k=5\\times 6\">2k=5\\times 6</span>. 解得 <span class=\"gk-math\" data-tex=\"k=15\">k=15</span>.","sourceNote":"","specialNote":"","answerAlternatives":[]},{"id":"2024-shanghai-q06","paperId":"2024-shanghai","number":6,"type":"fill","score":4,"lessonIds":["e3-6.3"],"difficulty":"基础","hint":"令x=1可得到所有系数的和，由此求n，再求组合数。","legacy":false,"legacyReason":"","searchText":"在 (x+1)^n 的二项展开式中，若各项系数和为 32，则 x^2 项的系数为 ________ . ","questionHtml":"在 <span class=\"gk-math\" data-tex=\"(x+1)^n\">(x+1)^n</span> 的二项展开式中，若各项系数和为 32，则 <span class=\"gk-math\" data-tex=\"x^2\">x^2</span> 项的系数为<span class=\"gk-blank\" aria-label=\"填空\">________</span>.","optionsHtml":[],"answerHtml":"10","answerKey":"","solutionHtml":"令 <span class=\"gk-math\" data-tex=\"x=1\">x=1</span>，则 <span class=\"gk-math\" data-tex=\"(1+1)^n=32\">(1+1)^n=32</span>， 即 <span class=\"gk-math\" data-tex=\"2^n=32\">2^n=32</span>， 解得 <span class=\"gk-math\" data-tex=\"n=5\">n=5</span>. <span class=\"gk-math\" data-tex=\"(x+1)^5\">(x+1)^5</span> 的展开式通项为 <span class=\"gk-math\" data-tex=\"T_{r+1}=\\mathrm{C}_5^r x^{5-r}\">T_{r+1}=\\mathrm{C}_5^r x^{5-r}</span>. 令 <span class=\"gk-math\" data-tex=\"5-r=2\">5-r=2</span>，得 <span class=\"gk-math\" data-tex=\"r=3\">r=3</span>，故 <span class=\"gk-math\" data-tex=\"x^2\">x^2</span> 项的系数为 <span class=\"gk-math\" data-tex=\"\\mathrm{C}_5^3=10\">\\mathrm{C}_5^3=10</span>.","sourceNote":"","specialNote":"","answerAlternatives":[]},{"id":"2024-shanghai-q07","paperId":"2024-shanghai","number":7,"type":"fill","score":5,"lessonIds":["e1-3.3"],"difficulty":"基础","hint":"抛物线准线是x=−1，距离9先给出点P的横坐标。","legacy":false,"legacyReason":"","searchText":"已知抛物线 y^2=4x 上有一点 P 到准线的距离为 9，那么点 P 到 x 轴的距离为 ________ . ","questionHtml":"已知抛物线 <span class=\"gk-math\" data-tex=\"y^2=4x\">y^2=4x</span> 上有一点 <span class=\"gk-math\" data-tex=\"P\">P</span> 到准线的距离为 9，那么点 <span class=\"gk-math\" data-tex=\"P\">P</span> 到 <span class=\"gk-math\" data-tex=\"x\">x</span> 轴的距离为<span class=\"gk-blank\" aria-label=\"填空\">________</span>.","optionsHtml":[],"answerHtml":"<span class=\"gk-math\" data-tex=\"4\\sqrt{2}\">4\\sqrt{2}</span>","answerKey":"","solutionHtml":"由抛物线 <span class=\"gk-math\" data-tex=\"y^2=4x\">y^2=4x</span> 的定义，准线方程为 <span class=\"gk-math\" data-tex=\"x=-1\">x=-1</span>. 设点 <span class=\"gk-math\" data-tex=\"P(x_0,y_0)\">P(x_0,y_0)</span>，则 <span class=\"gk-math\" data-tex=\"x_0+1=9\">x_0+1=9</span>， 解得 <span class=\"gk-math\" data-tex=\"x_0=8\">x_0=8</span>. 代入抛物线方程得 <span class=\"gk-math\" data-tex=\"y_0^2=4x_0=32\">y_0^2=4x_0=32</span>， 所以 <span class=\"gk-math\" data-tex=\"y_0=\\pm 4\\sqrt{2}\">y_0=\\pm 4\\sqrt{2}</span>. 因此点 <span class=\"gk-math\" data-tex=\"P\">P</span> 到 <span class=\"gk-math\" data-tex=\"x\">x</span> 轴的距离为 <span class=\"gk-math\" data-tex=\"4\\sqrt{2}\">4\\sqrt{2}</span>.","sourceNote":"","specialNote":"","answerAlternatives":[]},{"id":"2024-shanghai-q08","paperId":"2024-shanghai","number":8,"type":"fill","score":5,"lessonIds":["e3-7.1"],"difficulty":"进阶","hint":"三组被抽中的概率按题数计算，再分别乘答对概率相加。","legacy":false,"legacyReason":"","searchText":"小王参加知识竞赛，题库中 A 组题有 5000 道，B 组题有 4000 道，C 组题有 3000 道，若小王做对这三组题的概率依次为 0.92 ， 0.86 ， 0.72 ，则随机从题库中抽取一道题，小王做对的概率是 ________ . ","questionHtml":"小王参加知识竞赛，题库中 A 组题有 <span class=\"gk-math\" data-tex=\"5000\">5000</span> 道，B 组题有 <span class=\"gk-math\" data-tex=\"4000\">4000</span> 道，C 组题有 <span class=\"gk-math\" data-tex=\"3000\">3000</span> 道，若小王做对这三组题的概率依次为 <span class=\"gk-math\" data-tex=\"0.92\">0.92</span>，<span class=\"gk-math\" data-tex=\"0.86\">0.86</span>，<span class=\"gk-math\" data-tex=\"0.72\">0.72</span>，则随机从题库中抽取一道题，小王做对的概率是<span class=\"gk-blank\" aria-label=\"填空\">________</span>.","optionsHtml":[],"answerHtml":"0.85","answerKey":"","solutionHtml":"根据题意，三种题库数量比为 <span class=\"gk-math\" data-tex=\"5000:4000:3000=5:4:3\">5000:4000:3000=5:4:3</span>， 故所占比重分别为 <span class=\"gk-math\" data-tex=\"\\frac{5}{12}\">\\frac{5}{12}</span>，<span class=\"gk-math\" data-tex=\"\\frac{4}{12}\">\\frac{4}{12}</span>，<span class=\"gk-math\" data-tex=\"\\frac{3}{12}\">\\frac{3}{12}</span>. 所以随机选一题答对的概率为 <span class=\"gk-math\" data-tex=\"\\frac{5}{12}\\times 0.92+\\frac{4}{12}\\times 0.86+\\frac{3}{12}\\times 0.72=0.85\">\\frac{5}{12}\\times 0.92+\\frac{4}{12}\\times 0.86+\\frac{3}{12}\\times 0.72=0.85</span>.","sourceNote":"","specialNote":"","answerAlternatives":[]},{"id":"2024-shanghai-q09","paperId":"2024-shanghai","number":9,"type":"fill","score":5,"lessonIds":["7.2"],"difficulty":"进阶","hint":"虚数z实部为1，所以设z=1+bi且b≠0；结果是实数，虚部必须为0。","legacy":false,"legacyReason":"","searchText":"设 m\\in \\R ，若虚数 z 的实部为 1，且 z+\\frac{2}{z}=m ，则 m= ________ . ","questionHtml":"设 <span class=\"gk-math\" data-tex=\"m\\in \\R\">m\\in \\R</span>，若虚数 <span class=\"gk-math\" data-tex=\"z\">z</span> 的实部为 1，且 <span class=\"gk-math\" data-tex=\"z+\\frac{2}{z}=m\">z+\\frac{2}{z}=m</span>，则 <span class=\"gk-math\" data-tex=\"m=\">m=</span><span class=\"gk-blank\" aria-label=\"填空\">________</span>.","optionsHtml":[],"answerHtml":"2","answerKey":"","solutionHtml":"设 <span class=\"gk-math\" data-tex=\"z=1+b\\i\">z=1+b\\i</span>，<span class=\"gk-math\" data-tex=\"b\\in \\R\">b\\in \\R</span>，<span class=\"gk-math\" data-tex=\"b\\ne 0\">b\\ne 0</span>. 则 <span class=\"gk-math\" data-tex=\"z+\\frac{2}{z}=1+b\\i+\\frac{2}{1+b\\i} =\\left( \\frac{b^2+3}{1+b^2} \\right)+\\left( \\frac{b^3-b}{1+b^2} \\right)\\i\">z+\\frac{2}{z}=1+b\\i+\\frac{2}{1+b\\i} =\\left( \\frac{b^2+3}{1+b^2} \\right)+\\left( \\frac{b^3-b}{1+b^2} \\right)\\i</span>. 因为 <span class=\"gk-math\" data-tex=\"m\\in \\R\">m\\in \\R</span>，所以虚部为 0，即 <span class=\"gk-math\" data-tex=\"\\frac{b^3-b}{1+b^2}=0\">\\frac{b^3-b}{1+b^2}=0</span>. 解得 <span class=\"gk-math\" data-tex=\"b=\\pm 1\">b=\\pm 1</span>. 于是 <span class=\"gk-math\" data-tex=\"m=\\frac{b^2+3}{1+b^2}=2\">m=\\frac{b^2+3}{1+b^2}=2</span>.","sourceNote":"","specialNote":"","answerAlternatives":[]},{"id":"2024-shanghai-q10","paperId":"2024-shanghai","number":10,"type":"fill","score":5,"lessonIds":["e3-6.2","e3-6.1"],"difficulty":"进阶","hint":"两个奇数相乘是奇数，所以集合里最多放一个奇数，其他都必须是偶数。","legacy":false,"legacyReason":"","searchText":"已知某集合中的元素是不重复的数字组成的三位正整数，若该集合中任意两个数的积均为偶数，则该集合的元素个数的最大值为 ________ . ","questionHtml":"已知某集合中的元素是不重复的数字组成的三位正整数，若该集合中任意两个数的积均为偶数，则该集合的元素个数的最大值为<span class=\"gk-blank\" aria-label=\"填空\">________</span>.","optionsHtml":[],"answerHtml":"329","answerKey":"","solutionHtml":"根据题意，集合中至多只有一个奇数，其余均是偶数. 首先讨论三位数中的偶数.<br><br><ol class=\"gk-subparts\"><li>当个位为 <span class=\"gk-math\" data-tex=\"0\">0</span> 时，则百位和十位在剩余的 <span class=\"gk-math\" data-tex=\"9\">9</span> 个数字中选择两个进行排列，则这样的偶数有 <span class=\"gk-math\" data-tex=\"\\mathrm A_9^2=72\">\\mathrm A_9^2=72</span> 个；</li><li>当个位不为 <span class=\"gk-math\" data-tex=\"0\">0</span> 时，则个位有 <span class=\"gk-math\" data-tex=\"\\mathrm C_4^1\">\\mathrm C_4^1</span> 个数字可选，百位有 <span class=\"gk-math\" data-tex=\"\\mathrm C_8^1\">\\mathrm C_8^1</span> 个数字可选，十位有 <span class=\"gk-math\" data-tex=\"\\mathrm C_8^1\">\\mathrm C_8^1</span> 个数字可选，由分步乘法这样的偶数共有 <span class=\"gk-math\" data-tex=\"\\mathrm C_4^1\\mathrm C_8^1\\mathrm C_8^1=256\">\\mathrm C_4^1\\mathrm C_8^1\\mathrm C_8^1=256</span> 个.</li></ol> 最后再加上单独的奇数，所以集合中元素个数的最大值为 <span class=\"gk-math\" data-tex=\"72+256+1=329\">72+256+1=329</span>.","sourceNote":"","specialNote":"","answerAlternatives":[]},{"id":"2024-shanghai-q11","paperId":"2024-shanghai","number":11,"type":"fill","score":5,"lessonIds":["6.4","5.7"],"difficulty":"进阶","hint":"把两个三角形里的OT分别用正弦定理表示，再用OA=OB消去边长。","legacy":false,"legacyReason":"","searchText":"海上有灯塔 O ， A ， B 和船只 T ， A 在 O 的正东方向， B 在 O 的正北方向， OA=OB ， O ， A ， T ， B 按逆时针排列. 若 \\angle ATO=37^\\circ ， \\angle BTO=16.5^\\circ ，则 \\angle BOT= ________ （精确到 0.1^\\circ ）. ","questionHtml":"海上有灯塔 <span class=\"gk-math\" data-tex=\"O\">O</span>，<span class=\"gk-math\" data-tex=\"A\">A</span>，<span class=\"gk-math\" data-tex=\"B\">B</span> 和船只 <span class=\"gk-math\" data-tex=\"T\">T</span>，<span class=\"gk-math\" data-tex=\"A\">A</span> 在 <span class=\"gk-math\" data-tex=\"O\">O</span> 的正东方向，<span class=\"gk-math\" data-tex=\"B\">B</span> 在 <span class=\"gk-math\" data-tex=\"O\">O</span> 的正北方向，<span class=\"gk-math\" data-tex=\"OA=OB\">OA=OB</span>，<span class=\"gk-math\" data-tex=\"O\">O</span>，<span class=\"gk-math\" data-tex=\"A\">A</span>，<span class=\"gk-math\" data-tex=\"T\">T</span>，<span class=\"gk-math\" data-tex=\"B\">B</span> 按逆时针排列. 若 <span class=\"gk-math\" data-tex=\"\\angle ATO=37^\\circ\">\\angle ATO=37^\\circ</span>，<span class=\"gk-math\" data-tex=\"\\angle BTO=16.5^\\circ\">\\angle BTO=16.5^\\circ</span>，则 <span class=\"gk-math\" data-tex=\"\\angle BOT=\">\\angle BOT=</span><span class=\"gk-blank\" aria-label=\"填空\">________</span>（精确到 <span class=\"gk-math\" data-tex=\"0.1^\\circ\">0.1^\\circ</span>）.<br><br><figure class=\"gk-figure\"><button class=\"gk-zoom\" style=\"width:min(100%,270px)\" data-action=\"zoom-image\" data-label=\"高考题图\" data-src=\"./assets/gaokao/figures/2024/shanghai/q11_fig1.webp\" aria-label=\"放大高考题图\"><img src=\"./assets/gaokao/figures/2024/shanghai/q11_fig1.webp\" alt=\"高考题图，点击可放大\" width=\"254\" height=\"333\" style=\"aspect-ratio:254/333;width:100%\" loading=\"lazy\"></button></figure>","optionsHtml":[],"answerHtml":"<span class=\"gk-math\" data-tex=\"7.8^\\circ\">7.8^\\circ</span>","answerKey":"","solutionHtml":"设 <span class=\"gk-math\" data-tex=\"\\angle AOT=\\alpha\">\\angle AOT=\\alpha</span>，则 <span class=\"gk-math\" data-tex=\"\\angle BOT=90^\\circ-\\alpha\">\\angle BOT=90^\\circ-\\alpha</span>. 在 <span class=\"gk-math\" data-tex=\"\\triangle AOT\">\\triangle AOT</span> 中，由正弦定理得 <span class=\"gk-math\" data-tex=\"\\frac{OT}{OA}=\\frac{\\sin(143^\\circ-\\alpha)}{\\sin 37^\\circ}\">\\frac{OT}{OA}=\\frac{\\sin(143^\\circ-\\alpha)}{\\sin 37^\\circ}</span>. 在 <span class=\"gk-math\" data-tex=\"\\triangle BOT\">\\triangle BOT</span> 中，由正弦定理得 <span class=\"gk-math\" data-tex=\"\\frac{OT}{OB}=\\frac{\\sin(73.5^\\circ+\\alpha)}{\\sin 16.5^\\circ}\">\\frac{OT}{OB}=\\frac{\\sin(73.5^\\circ+\\alpha)}{\\sin 16.5^\\circ}</span>. 因为 <span class=\"gk-math\" data-tex=\"OA=OB\">OA=OB</span>，所以 <span class=\"gk-math\" data-tex=\"\\frac{\\sin(143^\\circ-\\alpha)}{\\sin 37^\\circ}=\\frac{\\sin(73.5^\\circ+\\alpha)}{\\sin 16.5^\\circ}\">\\frac{\\sin(143^\\circ-\\alpha)}{\\sin 37^\\circ}=\\frac{\\sin(73.5^\\circ+\\alpha)}{\\sin 16.5^\\circ}</span>. 利用计算器解得 <span class=\"gk-math\" data-tex=\"\\alpha\\approx82.2^\\circ\">\\alpha\\approx82.2^\\circ</span>，故 <span class=\"gk-math\" data-tex=\"\\angle BOT=90^\\circ-\\alpha\\approx7.8^\\circ\">\\angle BOT=90^\\circ-\\alpha\\approx7.8^\\circ</span>. 故答案为 <span class=\"gk-math\" data-tex=\"7.8^\\circ\">7.8^\\circ</span>.","sourceNote":"","specialNote":"","answerAlternatives":[]},{"id":"2024-shanghai-q12","paperId":"2024-shanghai","number":12,"type":"fill","score":5,"lessonIds":["e2-4.3","1.3"],"difficulty":"挑战","hint":"两个区间里的数相减，先写出同一区间内的差与两个区间之间的差。","legacy":false,"legacyReason":"","searchText":"等比数列 \\{a_n\\} 满足首项 a_1>0 ，公比 q>1 ，记 I_n=\\{x-y\\mid x,y\\in [a_1,a_2]\\cup [a_n,a_{n+1}]\\} ，若对任意正整数 n ，集合 I_n 都是闭区间，则 q 的取值范围是 ________ . ","questionHtml":"等比数列 <span class=\"gk-math\" data-tex=\"\\{a_n\\}\">\\{a_n\\}</span> 满足首项 <span class=\"gk-math\" data-tex=\"a_1&gt;0\">a_1&gt;0</span>，公比 <span class=\"gk-math\" data-tex=\"q&gt;1\">q&gt;1</span>，记 <span class=\"gk-math\" data-tex=\"I_n=\\{x-y\\mid x,y\\in [a_1,a_2]\\cup [a_n,a_{n+1}]\\}\">I_n=\\{x-y\\mid x,y\\in [a_1,a_2]\\cup [a_n,a_{n+1}]\\}</span>，若对任意正整数 <span class=\"gk-math\" data-tex=\"n\">n</span>，集合 <span class=\"gk-math\" data-tex=\"I_n\">I_n</span> 都是闭区间，则 <span class=\"gk-math\" data-tex=\"q\">q</span> 的取值范围是<span class=\"gk-blank\" aria-label=\"填空\">________</span>.","optionsHtml":[],"answerHtml":"<span class=\"gk-math\" data-tex=\"q\\ge 2\">q\\ge 2</span>","answerKey":"","solutionHtml":"由题设， <span class=\"gk-math\" data-tex=\"a_n=a_1q^{n-1}\">a_n=a_1q^{n-1}</span>. 因为 <span class=\"gk-math\" data-tex=\"a_1&gt;0\">a_1&gt;0</span>，<span class=\"gk-math\" data-tex=\"q&gt;1\">q&gt;1</span>，所以 <span class=\"gk-math\" data-tex=\"a_{n+1}&gt;a_n\">a_{n+1}&gt;a_n</span>. 当 <span class=\"gk-math\" data-tex=\"n\\ge 2\">n\\ge 2</span> 时，不妨设 <span class=\"gk-math\" data-tex=\"x\\ge y\">x\\ge y</span>. 则 <span class=\"gk-math\" data-tex=\"x-y\\in [0,a_2-a_1]\\cup [a_n-a_2,a_{n+1}-a_1]\\cup [0,a_{n+1}-a_n]\">x-y\\in [0,a_2-a_1]\\cup [a_n-a_2,a_{n+1}-a_1]\\cup [0,a_{n+1}-a_n]</span>. 要使 <span class=\"gk-math\" data-tex=\"I_n\">I_n</span> 为闭区间，就必须有 <span class=\"gk-math\" data-tex=\"a_{n+1}-a_n\\ge a_n-a_2\">a_{n+1}-a_n\\ge a_n-a_2</span>. 即 <span class=\"gk-math\" data-tex=\"a_1q^{n-1}(q-2)+a_2\\ge 0\">a_1q^{n-1}(q-2)+a_2\\ge 0</span>. 等价于 <span class=\"gk-math\" data-tex=\"q-2\\ge -\\frac{1}{q^{n-2}}\">q-2\\ge -\\frac{1}{q^{n-2}}</span>. 由于 <span class=\"gk-math\" data-tex=\"q&gt;1\">q&gt;1</span>，当 <span class=\"gk-math\" data-tex=\"n\\to +\\infty\">n\\to +\\infty</span> 时，<span class=\"gk-math\" data-tex=\"-\\frac{1}{q^{n-2}}\\to 0\">-\\frac{1}{q^{n-2}}\\to 0</span>，故必有 <span class=\"gk-math\" data-tex=\"q-2\\ge 0\">q-2\\ge 0</span>. 因此 <span class=\"gk-math\" data-tex=\"q\\ge 2\">q\\ge 2</span>. 反之，若 <span class=\"gk-math\" data-tex=\"q\\ge 2\">q\\ge 2</span>，则对任意 <span class=\"gk-math\" data-tex=\"n\\ge 2\">n\\ge 2</span>，有 <span class=\"gk-math\" data-tex=\"a_{n+1}-a_n\\ge a_2-a_1\">a_{n+1}-a_n\\ge a_2-a_1</span>，且<br><br><span class=\"gk-math\" data-tex=\"a_{n+1}-a_n-(a_n-a_2)=a_1\\bigl(q^{n-1}(q-2)+q\\bigr)\\ge 0\">a_{n+1}-a_n-(a_n-a_2)=a_1\\bigl(q^{n-1}(q-2)+q\\bigr)\\ge 0</span>.<br><br>所以差集中的三个区间首尾相接，<span class=\"gk-math\" data-tex=\"I_n\">I_n</span> 为闭区间；<span class=\"gk-math\" data-tex=\"n=1\">n=1</span> 时结论显然成立. 故 <span class=\"gk-math\" data-tex=\"q\">q</span> 的取值范围为 <span class=\"gk-math\" data-tex=\"[2,+\\infty)\">[2,+\\infty)</span>.","sourceNote":"","specialNote":"","answerAlternatives":[]},{"id":"2024-shanghai-q13","paperId":"2024-shanghai","number":13,"type":"single","score":4,"lessonIds":["e3-8.1"],"difficulty":"基础","hint":"相关系数为正表示总体有一起上升的趋势，不能说每次都必然上升。","legacy":false,"legacyReason":"","searchText":"已知气温（单位 ^{\\circ}\\mathrm C ）和海水表层温度（单位：摄氏度）相关，且相关系数为正数，对此描述正确的是（ ） 随着气温由低变高，海水表层温度由低变高 随着气温由低变高，海水表层温度由高变低 随着气温由低变高，海水表层温度有由低变高的趋势 随着气温由低变高，海水表层温度有由高变低的趋势","questionHtml":"已知气温（单位 <span class=\"gk-math\" data-tex=\"^{\\circ}\\mathrm C\">^{\\circ}\\mathrm C</span>）和海水表层温度（单位：摄氏度）相关，且相关系数为正数，对此描述正确的是（ ）","optionsHtml":["随着气温由低变高，海水表层温度由低变高","随着气温由低变高，海水表层温度由高变低","随着气温由低变高，海水表层温度有由低变高的趋势","随着气温由低变高，海水表层温度有由高变低的趋势"],"answerHtml":"C","answerKey":"C","solutionHtml":"A，B. 当气温高时，海水表层温度变高变低不确定，故 A，B 错误.<br><br>C，D. 因为相关系数为正，故随着气温由低变高时，海水表层温度呈上升趋势，故 C 正确，D 错误.<br><br>故选 C.","sourceNote":"","specialNote":"","answerAlternatives":[]},{"id":"2024-shanghai-q14","paperId":"2024-shanghai","number":14,"type":"single","score":4,"lessonIds":["5.4","5.5"],"difficulty":"基础","hint":"把四个表达式化成单个三角函数或常数，再比较周期。","legacy":false,"legacyReason":"","searchText":"下列函数 f(x) 的最小正周期是 2\\pi 的是（ ） y=\\sin x+\\cos x y=\\sin x\\cos x y=\\sin^2 x+\\cos^2 x y=\\sin^2 x-\\cos^2 x","questionHtml":"下列函数 <span class=\"gk-math\" data-tex=\"f(x)\">f(x)</span> 的最小正周期是 <span class=\"gk-math\" data-tex=\"2\\pi\">2\\pi</span> 的是（ ）","optionsHtml":["<span class=\"gk-math\" data-tex=\"y=\\sin x+\\cos x\">y=\\sin x+\\cos x</span>","<span class=\"gk-math\" data-tex=\"y=\\sin x\\cos x\">y=\\sin x\\cos x</span>","<span class=\"gk-math\" data-tex=\"y=\\sin^2 x+\\cos^2 x\">y=\\sin^2 x+\\cos^2 x</span>","<span class=\"gk-math\" data-tex=\"y=\\sin^2 x-\\cos^2 x\">y=\\sin^2 x-\\cos^2 x</span>"],"answerHtml":"A","answerKey":"A","solutionHtml":"因为 <span class=\"gk-math\" data-tex=\"\\sin x+\\cos x=\\sqrt{2}\\sin\\left( x+\\frac{\\pi}{4} \\right)\">\\sin x+\\cos x=\\sqrt{2}\\sin\\left( x+\\frac{\\pi}{4} \\right)</span>， 其最小正周期为 <span class=\"gk-math\" data-tex=\"2\\pi\">2\\pi</span>.<br><br>又 <span class=\"gk-math\" data-tex=\"\\sin x\\cos x=\\frac{1}{2}\\sin 2x\">\\sin x\\cos x=\\frac{1}{2}\\sin 2x</span>， 最小正周期为 <span class=\"gk-math\" data-tex=\"\\pi\">\\pi</span>； <span class=\"gk-math\" data-tex=\"\\sin^2 x+\\cos^2 x=1\">\\sin^2 x+\\cos^2 x=1</span> 为常值函数； <span class=\"gk-math\" data-tex=\"\\sin^2 x-\\cos^2 x=-\\cos 2x\">\\sin^2 x-\\cos^2 x=-\\cos 2x</span> 最小正周期为 <span class=\"gk-math\" data-tex=\"\\pi\">\\pi</span>. 故选 A.","sourceNote":"","specialNote":"","answerAlternatives":[]},{"id":"2024-shanghai-q15","paperId":"2024-shanghai","number":15,"type":"single","score":5,"lessonIds":["e1-1.2","1.4"],"difficulty":"进阶","hint":"题目说任意三个位置向量都线性相关；想象加入z轴方向后，哪些点会组成三个独立方向。","legacy":false,"legacyReason":"","searchText":"已知空间直角坐标系 Oxyz 中的点集 \\Omega ，对任意的 P_1 ， P_2 ， P_3\\in \\Omega ，均存在不全为 0 的实数 \\lambda_1 ， \\lambda_2 ， \\lambda_3 ，使得 \\lambda_1\\overrightarrow{OP_1}+\\lambda_2\\overrightarrow{OP_2}+\\lambda_3\\overrightarrow{OP_3}=\\bs{0} . 若 (1,0,0)\\in \\Omega ，则 (0,0,1)\\notin \\Omega 的一个充分条件是（ ） (0,0,0)\\in \\Omega (-1,0,0)\\in \\Omega (0,-1,0)\\in \\Omega (0,0,-1)\\in \\Omega","questionHtml":"已知空间直角坐标系 <span class=\"gk-math\" data-tex=\"Oxyz\">Oxyz</span> 中的点集 <span class=\"gk-math\" data-tex=\"\\Omega\">\\Omega</span>，对任意的 <span class=\"gk-math\" data-tex=\"P_1\">P_1</span>，<span class=\"gk-math\" data-tex=\"P_2\">P_2</span>，<span class=\"gk-math\" data-tex=\"P_3\\in \\Omega\">P_3\\in \\Omega</span>，均存在不全为 <span class=\"gk-math\" data-tex=\"0\">0</span> 的实数 <span class=\"gk-math\" data-tex=\"\\lambda_1\">\\lambda_1</span>，<span class=\"gk-math\" data-tex=\"\\lambda_2\">\\lambda_2</span>，<span class=\"gk-math\" data-tex=\"\\lambda_3\">\\lambda_3</span>，使得 <span class=\"gk-math\" data-tex=\"\\lambda_1\\overrightarrow{OP_1}+\\lambda_2\\overrightarrow{OP_2}+\\lambda_3\\overrightarrow{OP_3}=\\bs{0}\">\\lambda_1\\overrightarrow{OP_1}+\\lambda_2\\overrightarrow{OP_2}+\\lambda_3\\overrightarrow{OP_3}=\\bs{0}</span>. 若 <span class=\"gk-math\" data-tex=\"(1,0,0)\\in \\Omega\">(1,0,0)\\in \\Omega</span>，则 <span class=\"gk-math\" data-tex=\"(0,0,1)\\notin \\Omega\">(0,0,1)\\notin \\Omega</span> 的一个充分条件是（ ）","optionsHtml":["<span class=\"gk-math\" data-tex=\"(0,0,0)\\in \\Omega\">(0,0,0)\\in \\Omega</span>","<span class=\"gk-math\" data-tex=\"(-1,0,0)\\in \\Omega\">(-1,0,0)\\in \\Omega</span>","<span class=\"gk-math\" data-tex=\"(0,-1,0)\\in \\Omega\">(0,-1,0)\\in \\Omega</span>","<span class=\"gk-math\" data-tex=\"(0,0,-1)\\in \\Omega\">(0,0,-1)\\in \\Omega</span>"],"answerHtml":"C","answerKey":"C","solutionHtml":"根据题意，这三个向量 <span class=\"gk-math\" data-tex=\"\\overrightarrow{OP_1}\">\\overrightarrow{OP_1}</span>，<span class=\"gk-math\" data-tex=\"\\overrightarrow{OP_2}\">\\overrightarrow{OP_2}</span>，<span class=\"gk-math\" data-tex=\"\\overrightarrow{OP_3}\">\\overrightarrow{OP_3}</span> 共面，即这三个向量不能构成空间的一个基底.<br><br>A. 在空间直角坐标系中，<span class=\"gk-math\" data-tex=\"(0,0,0)\">(0,0,0)</span>，<span class=\"gk-math\" data-tex=\"(1,0,0)\">(1,0,0)</span>，<span class=\"gk-math\" data-tex=\"(0,0,1)\">(0,0,1)</span> 三个向量共面，则当 <span class=\"gk-math\" data-tex=\"(0,0,0)\">(0,0,0)</span>，<span class=\"gk-math\" data-tex=\"(1,0,0)\\in \\Omega\">(1,0,0)\\in \\Omega</span> 时无法推出 <span class=\"gk-math\" data-tex=\"(0,0,1)\\notin \\Omega\">(0,0,1)\\notin \\Omega</span>，A 错误；<br><br>B. 在空间直角坐标系中，<span class=\"gk-math\" data-tex=\"(-1,0,0)\">(-1,0,0)</span>，<span class=\"gk-math\" data-tex=\"(1,0,0)\">(1,0,0)</span>，<span class=\"gk-math\" data-tex=\"(0,0,1)\">(0,0,1)</span> 三个向量共面，则当 <span class=\"gk-math\" data-tex=\"(-1,0,0)\">(-1,0,0)</span>，<span class=\"gk-math\" data-tex=\"(1,0,0)\\in \\Omega\">(1,0,0)\\in \\Omega</span> 时无法推出 <span class=\"gk-math\" data-tex=\"(0,0,1)\\notin \\Omega\">(0,0,1)\\notin \\Omega</span>，B 错误；<br><br>C. 在空间直角坐标系中，<span class=\"gk-math\" data-tex=\"(1,0,0)\">(1,0,0)</span>，<span class=\"gk-math\" data-tex=\"(0,0,1)\">(0,0,1)</span>，<span class=\"gk-math\" data-tex=\"(0,-1,0)\">(0,-1,0)</span> 三个向量不共面，可构成空间的一个基底，则由 <span class=\"gk-math\" data-tex=\"(1,0,0)\">(1,0,0)</span>，<span class=\"gk-math\" data-tex=\"(0,-1,0)\\in \\Omega\">(0,-1,0)\\in \\Omega</span> 能推出 <span class=\"gk-math\" data-tex=\"(0,0,1)\\notin \\Omega\">(0,0,1)\\notin \\Omega</span>，C 正确；<br><br>D. 在空间直角坐标系中，<span class=\"gk-math\" data-tex=\"(1,0,0)\">(1,0,0)</span>，<span class=\"gk-math\" data-tex=\"(0,0,1)\">(0,0,1)</span>，<span class=\"gk-math\" data-tex=\"(0,0,-1)\">(0,0,-1)</span> 三个向量共面，则当 <span class=\"gk-math\" data-tex=\"(0,0,-1)\">(0,0,-1)</span>，<span class=\"gk-math\" data-tex=\"(1,0,0)\\in \\Omega\">(1,0,0)\\in \\Omega</span> 时无法推出 <span class=\"gk-math\" data-tex=\"(0,0,1)\\notin \\Omega\">(0,0,1)\\notin \\Omega</span>，D 错误.<br><br>故选 C.","sourceNote":"","specialNote":"","answerAlternatives":[]},{"id":"2024-shanghai-q16","paperId":"2024-shanghai","number":16,"type":"single","score":5,"lessonIds":["3.2","e2-5.3"],"difficulty":"挑战","hint":"M里的点是“刷新左边所有历史高度”的点；先看看偶函数和严格增函数能不能符合。","legacy":false,"legacyReason":"","searchText":"已知函数 f(x) 的定义域为 \\R ，定义集合 M=\\{x_0\\mid x_0\\in \\R,\\ \\forall x\\in(-\\infty,x_0),\\ f(x)<f(x_0)\\} . 在使得 M=[-1,1] 的所有 f(x) 中，下列成立的是（ ） 存在 y=f(x) 是偶函数 存在 y=f(x) 在 x=2 处取最大值 存在 y=f(x) 是严格增函数 存在 y=f(x) 在 x=-1 处取到极小值","questionHtml":"已知函数 <span class=\"gk-math\" data-tex=\"f(x)\">f(x)</span> 的定义域为 <span class=\"gk-math\" data-tex=\"\\R\">\\R</span>，定义集合 <span class=\"gk-math\" data-tex=\"M=\\{x_0\\mid x_0\\in \\R,\\ \\forall x\\in(-\\infty,x_0),\\ f(x)&lt;f(x_0)\\}\">M=\\{x_0\\mid x_0\\in \\R,\\ \\forall x\\in(-\\infty,x_0),\\ f(x)&lt;f(x_0)\\}</span>. 在使得 <span class=\"gk-math\" data-tex=\"M=[-1,1]\">M=[-1,1]</span> 的所有 <span class=\"gk-math\" data-tex=\"f(x)\">f(x)</span> 中，下列成立的是（ ）","optionsHtml":["存在 <span class=\"gk-math\" data-tex=\"y=f(x)\">y=f(x)</span> 是偶函数","存在 <span class=\"gk-math\" data-tex=\"y=f(x)\">y=f(x)</span> 在 <span class=\"gk-math\" data-tex=\"x=2\">x=2</span> 处取最大值","存在 <span class=\"gk-math\" data-tex=\"y=f(x)\">y=f(x)</span> 是严格增函数","存在 <span class=\"gk-math\" data-tex=\"y=f(x)\">y=f(x)</span> 在 <span class=\"gk-math\" data-tex=\"x=-1\">x=-1</span> 处取到极小值"],"answerHtml":"B","answerKey":"B","solutionHtml":"A：若 <span class=\"gk-math\" data-tex=\"f(x)\">f(x)</span> 是偶函数，取 <span class=\"gk-math\" data-tex=\"x_0=1\\in[-1,1]\">x_0=1\\in[-1,1]</span>，则对任意 <span class=\"gk-math\" data-tex=\"x&lt;1\">x&lt;1</span> 有 <span class=\"gk-math\" data-tex=\"f(x)&lt;f(1)\">f(x)&lt;f(1)</span>，但 <span class=\"gk-math\" data-tex=\"f(-1)=f(1)\">f(-1)=f(1)</span>，矛盾.<br><br>B：可构造 <div class=\"gk-math display\" data-tex=\"f(x)=\n\\begin{cases}\n-2, &amp; x&lt;-1,\\\\\nx, &amp; -1\\le x\\le 1,\\\\\n1, &amp; x&gt;1,\n\\end{cases}\">f(x)=\n\\begin{cases}\n-2, &amp; x&lt;-1,\\\\\nx, &amp; -1\\le x\\le 1,\\\\\n1, &amp; x&gt;1,\n\\end{cases}</div> 此时 <span class=\"gk-math\" data-tex=\"M=[-1,1]\">M=[-1,1]</span>，且 <span class=\"gk-math\" data-tex=\"f(2)=1\">f(2)=1</span> 为最大值.<br><br>C：若 <span class=\"gk-math\" data-tex=\"f(x)\">f(x)</span> 严格递增，则对任意 <span class=\"gk-math\" data-tex=\"x_0\\in \\R\">x_0\\in \\R</span> 均满足定义，因此 <span class=\"gk-math\" data-tex=\"M=\\R\">M=\\R</span>，矛盾.<br><br>D：若 <span class=\"gk-math\" data-tex=\"f(x)\">f(x)</span> 在 <span class=\"gk-math\" data-tex=\"x=-1\">x=-1</span> 处取极小值，则不可能对所有 <span class=\"gk-math\" data-tex=\"x&lt;-1\">x&lt;-1</span> 都有 <span class=\"gk-math\" data-tex=\"f(x)&lt;f(-1)\">f(x)&lt;f(-1)</span>，与 <span class=\"gk-math\" data-tex=\"M\">M</span> 的定义矛盾.<br><br>故选 B.","sourceNote":"","specialNote":"","answerAlternatives":[]},{"id":"2024-shanghai-q17","paperId":"2024-shanghai","number":17,"type":"written","score":14,"lessonIds":["8.3","8.6","e1-1.4"],"difficulty":"进阶","hint":"第一问旋转出来的是圆锥，先求AO与PO；第二问注意等边侧面里中线垂直对边。","legacy":false,"legacyReason":"","searchText":"如图，在正四棱锥 P-ABCD 中， O 为底面 ABCD 的中心. 若 AP=5 ， AD=3\\sqrt{2} ，将 \\triangle POA 绕直线 PO 旋转一周，求所得旋转体的体积； 若 AP=AD ， E 为 PB 的中点，求直线 BD 与平面 AEC 所成角的大小. ","questionHtml":"如图，在正四棱锥 <span class=\"gk-math\" data-tex=\"P-ABCD\">P-ABCD</span> 中，<span class=\"gk-math\" data-tex=\"O\">O</span> 为底面 <span class=\"gk-math\" data-tex=\"ABCD\">ABCD</span> 的中心.<br><br><ol class=\"gk-subparts\"><li>若 <span class=\"gk-math\" data-tex=\"AP=5\">AP=5</span>，<span class=\"gk-math\" data-tex=\"AD=3\\sqrt{2}\">AD=3\\sqrt{2}</span>，将 <span class=\"gk-math\" data-tex=\"\\triangle POA\">\\triangle POA</span> 绕直线 <span class=\"gk-math\" data-tex=\"PO\">PO</span> 旋转一周，求所得旋转体的体积；</li><li>若 <span class=\"gk-math\" data-tex=\"AP=AD\">AP=AD</span>，<span class=\"gk-math\" data-tex=\"E\">E</span> 为 <span class=\"gk-math\" data-tex=\"PB\">PB</span> 的中点，求直线 <span class=\"gk-math\" data-tex=\"BD\">BD</span> 与平面 <span class=\"gk-math\" data-tex=\"AEC\">AEC</span> 所成角的大小.</li></ol><br><br><figure class=\"gk-figure\"><button class=\"gk-zoom\" style=\"width:min(100%,565px)\" data-action=\"zoom-image\" data-label=\"高考题图\" data-src=\"./assets/gaokao/figures/2024/shanghai/q17_fig1.webp\" aria-label=\"放大高考题图\"><img src=\"./assets/gaokao/figures/2024/shanghai/q17_fig1.webp\" alt=\"高考题图，点击可放大\" width=\"549\" height=\"489\" style=\"aspect-ratio:549/489;width:100%\" loading=\"lazy\"></button></figure>","optionsHtml":[],"answerHtml":"<span>见下方分步解析</span>","answerKey":"","solutionHtml":"<ol class=\"gk-subparts\"><li>因为正四棱锥满足 <span class=\"gk-math\" data-tex=\"PO\\perp \\text{平面 }ABCD\">PO\\perp \\text{平面 }ABCD</span>，而 <span class=\"gk-math\" data-tex=\"AO\\subset \\text{平面 }ABCD\">AO\\subset \\text{平面 }ABCD</span>，故 <span class=\"gk-math\" data-tex=\"PO\\perp AO\">PO\\perp AO</span>. 又底面 <span class=\"gk-math\" data-tex=\"ABCD\">ABCD</span> 是正方形，且 <span class=\"gk-math\" data-tex=\"AD=3\\sqrt{2}\">AD=3\\sqrt{2}</span>，所以 <span class=\"gk-math\" data-tex=\"AO=3\">AO=3</span>. 由勾股定理， <span class=\"gk-math\" data-tex=\"PO=\\sqrt{PA^2-AO^2}=\\sqrt{25-9}=4\">PO=\\sqrt{PA^2-AO^2}=\\sqrt{25-9}=4</span>. <span class=\"gk-math\" data-tex=\"\\triangle POA\">\\triangle POA</span> 绕 <span class=\"gk-math\" data-tex=\"PO\">PO</span> 旋转一周形成的是圆锥，其高为 4，底面半径为 3，因此体积为 <span class=\"gk-math\" data-tex=\"V=\\frac{1}{3}\\pi\\times 3^2\\times 4=12\\pi\">V=\\frac{1}{3}\\pi\\times 3^2\\times 4=12\\pi</span>.</li><li>连接 <span class=\"gk-math\" data-tex=\"EA\">EA</span>，<span class=\"gk-math\" data-tex=\"EO\">EO</span>，<span class=\"gk-math\" data-tex=\"EC\">EC</span>. 根据题意结合正四棱锥的性质，每个侧面都是等边三角形.<br><br><figure class=\"gk-figure\"><button class=\"gk-zoom\" style=\"width:min(100%,352px)\" data-action=\"zoom-image\" data-label=\"高考题图\" data-src=\"./assets/gaokao/figures/2024/shanghai/q17_solution_fig1.webp\" aria-label=\"放大高考题图\"><img src=\"./assets/gaokao/figures/2024/shanghai/q17_solution_fig1.webp\" alt=\"高考题图，点击可放大\" width=\"336\" height=\"306\" style=\"aspect-ratio:336/306;width:100%\" loading=\"lazy\"></button></figure><br><br>由 <span class=\"gk-math\" data-tex=\"E\">E</span> 是 <span class=\"gk-math\" data-tex=\"PB\">PB</span> 的中点，得 <span class=\"gk-math\" data-tex=\"AE\\perp PB\">AE\\perp PB</span>，<span class=\"gk-math\" data-tex=\"CE\\perp PB\">CE\\perp PB</span>. 又 <span class=\"gk-math\" data-tex=\"AE\\cap CE=E\">AE\\cap CE=E</span>，且 <span class=\"gk-math\" data-tex=\"AE\">AE</span>，<span class=\"gk-math\" data-tex=\"CE\\subset \\text{平面 }ACE\">CE\\subset \\text{平面 }ACE</span>，故 <span class=\"gk-math\" data-tex=\"PB\\perp \\text{平面 }ACE\">PB\\perp \\text{平面 }ACE</span>. 于是 <span class=\"gk-math\" data-tex=\"BE\\perp \\text{平面 }ACE\">BE\\perp \\text{平面 }ACE</span>. 又 <span class=\"gk-math\" data-tex=\"BD\\cap \\text{平面 }ACE=O\">BD\\cap \\text{平面 }ACE=O</span>， 所以直线 <span class=\"gk-math\" data-tex=\"BD\">BD</span> 与平面 <span class=\"gk-math\" data-tex=\"AEC\">AEC</span> 所成角为 <span class=\"gk-math\" data-tex=\"\\angle BOE\">\\angle BOE</span>. 不妨设 <span class=\"gk-math\" data-tex=\"AP=AD=6\">AP=AD=6</span>， 则 <span class=\"gk-math\" data-tex=\"BO=3\\sqrt{2}\">BO=3\\sqrt{2}</span>，<span class=\"gk-math\" data-tex=\"BE=3\">BE=3</span>. 因此 <span class=\"gk-math\" data-tex=\"\\sin \\angle BOE=\\frac{BE}{BO}=\\frac{3}{3\\sqrt{2}}=\\frac{\\sqrt{2}}{2}\">\\sin \\angle BOE=\\frac{BE}{BO}=\\frac{3}{3\\sqrt{2}}=\\frac{\\sqrt{2}}{2}</span>. 又线面角属于 <span class=\"gk-math\" data-tex=\"\\left[ 0,\\frac{\\pi}{2} \\right]\">\\left[ 0,\\frac{\\pi}{2} \\right]</span>，故 <span class=\"gk-math\" data-tex=\"\\angle BOE=\\frac{\\pi}{4}\">\\angle BOE=\\frac{\\pi}{4}</span>.</li></ol>","sourceNote":"","specialNote":"","answerAlternatives":[]},{"id":"2024-shanghai-q18","paperId":"2024-shanghai","number":18,"type":"written","score":14,"lessonIds":["4.4","e2-4.2","4.3"],"difficulty":"进阶","hint":"第一问先由logₐ4=2求底数；第二问用“中间项的2倍=前后两项之和”。","legacy":false,"legacyReason":"","searchText":"若 f(x)=\\log_a x （ a>0 ， a\\ne 1 ）. y=f(x) 过 (4,2) ，求 f(2x-2)<f(x) 的解集； 存在 x 使得 f(x+1) ， f(ax) ， f(x+2) 成等差数列，求 a 的取值范围. ","questionHtml":"若 <span class=\"gk-math\" data-tex=\"f(x)=\\log_a x\">f(x)=\\log_a x</span>（<span class=\"gk-math\" data-tex=\"a&gt;0\">a&gt;0</span>，<span class=\"gk-math\" data-tex=\"a\\ne 1\">a\\ne 1</span>）.<br><br><ol class=\"gk-subparts\"><li><span class=\"gk-math\" data-tex=\"y=f(x)\">y=f(x)</span> 过 <span class=\"gk-math\" data-tex=\"(4,2)\">(4,2)</span>，求 <span class=\"gk-math\" data-tex=\"f(2x-2)&lt;f(x)\">f(2x-2)&lt;f(x)</span> 的解集；</li><li>存在 <span class=\"gk-math\" data-tex=\"x\">x</span> 使得 <span class=\"gk-math\" data-tex=\"f(x+1)\">f(x+1)</span>，<span class=\"gk-math\" data-tex=\"f(ax)\">f(ax)</span>，<span class=\"gk-math\" data-tex=\"f(x+2)\">f(x+2)</span> 成等差数列，求 <span class=\"gk-math\" data-tex=\"a\">a</span> 的取值范围.</li></ol>","optionsHtml":[],"answerHtml":"<span>见下方分步解析</span>","answerKey":"","solutionHtml":"<ol class=\"gk-subparts\"><li>因为 <span class=\"gk-math\" data-tex=\"y=f(x)\">y=f(x)</span> 过 <span class=\"gk-math\" data-tex=\"(4,2)\">(4,2)</span>，所以 <span class=\"gk-math\" data-tex=\"\\log_a 4=2\">\\log_a 4=2</span>， 即 <span class=\"gk-math\" data-tex=\"a^2=4\">a^2=4</span>. 又 <span class=\"gk-math\" data-tex=\"a&gt;0\">a&gt;0</span>，<span class=\"gk-math\" data-tex=\"a\\ne 1\">a\\ne 1</span>，故 <span class=\"gk-math\" data-tex=\"a=2\">a=2</span>. 于是 <span class=\"gk-math\" data-tex=\"f(x)=\\log_2 x\">f(x)=\\log_2 x</span> 在 <span class=\"gk-math\" data-tex=\"(0,+\\infty)\">(0,+\\infty)</span> 上单调递增，所以 <span class=\"gk-math\" data-tex=\"f(2x-2)&lt;f(x) \\iff 0&lt;2x-2&lt;x\">f(2x-2)&lt;f(x) \\iff 0&lt;2x-2&lt;x</span>. 解得 <span class=\"gk-math\" data-tex=\"1&lt;x&lt;2\">1&lt;x&lt;2</span>.</li><li>由 <span class=\"gk-math\" data-tex=\"f(x+1)\">f(x+1)</span>，<span class=\"gk-math\" data-tex=\"f(ax)\">f(ax)</span>，<span class=\"gk-math\" data-tex=\"f(x+2)\">f(x+2)</span> 成等差数列，得 <span class=\"gk-math\" data-tex=\"2f(ax)=f(x+1)+f(x+2)\">2f(ax)=f(x+1)+f(x+2)</span>. 即 <span class=\"gk-math\" data-tex=\"2\\log_a(ax)=\\log_a(x+1)+\\log_a(x+2)\">2\\log_a(ax)=\\log_a(x+1)+\\log_a(x+2)</span>. 因此 <span class=\"gk-math\" data-tex=\"a^2x^2=(x+1)(x+2)\">a^2x^2=(x+1)(x+2)</span>. 又 <span class=\"gk-math\" data-tex=\"x&gt;0\">x&gt;0</span>，所以 <div class=\"gk-math display\" data-tex=\"a^2=\\frac{x^2+3x+2}{x^2}=1+\\frac{3}{x}+\\frac{2}{x^2}=2\\left( \\frac{1}{x}+\\frac{3}{4} \\right)^2-\\frac{1}{8}\">a^2=\\frac{x^2+3x+2}{x^2}=1+\\frac{3}{x}+\\frac{2}{x^2}=2\\left( \\frac{1}{x}+\\frac{3}{4} \\right)^2-\\frac{1}{8}</div> 令 <span class=\"gk-math\" data-tex=\"t=\\frac{1}{x}\\in(0,+\\infty)\">t=\\frac{1}{x}\\in(0,+\\infty)</span>， 则 <span class=\"gk-math\" data-tex=\"a^2=2\\left( t+\\frac{3}{4} \\right)^2-\\frac{1}{8}\">a^2=2\\left( t+\\frac{3}{4} \\right)^2-\\frac{1}{8}</span>. 其在 <span class=\"gk-math\" data-tex=\"(0,+\\infty)\">(0,+\\infty)</span> 上的值域为 <span class=\"gk-math\" data-tex=\"(1,+\\infty)\">(1,+\\infty)</span>，故 <span class=\"gk-math\" data-tex=\"a^2&gt;1\">a^2&gt;1</span>. 由于 <span class=\"gk-math\" data-tex=\"a&gt;0\">a&gt;0</span>，得 <span class=\"gk-math\" data-tex=\"a&gt;1\">a&gt;1</span>.</li></ol>","sourceNote":"","specialNote":"","answerAlternatives":[]},{"id":"2024-shanghai-q19","paperId":"2024-shanghai","number":19,"type":"written","score":14,"lessonIds":["9.2","e3-8.3"],"difficulty":"进阶","hint":"先统计目标时长的样本人数；独立性检验要把原表合并成2×2表。","legacy":false,"legacyReason":"","searchText":"某地区为调查初中学生体育锻炼时长与学业成绩的关系，从该地区 29000 名初中生中抽取 580 人，得到日均体育锻炼时长（表中简称时长）与学业成绩的数据如下表所示： 时长 [0,0.5) [0.5,1) [1,1.5) [1.5,2) [2,2.5) 合计 优秀 5 44 42 3 1 95 不优秀 134 147 137 40 27 485 合计 139 191 179 43 28 580 估计该地区 29000 名初中生中体育锻炼时长大于 1 小时人数； 估计该地区初中生平均日均体育锻炼时长（结果精确到 0.1 小时）； 判断是否有 95% 的把握认为该地区初中生学业成绩优秀与日均体育锻炼时长不小于 1 小时且小于 2 小时有关？ （附： \\chi^2=\\frac{n(ad-bc)^2}{(a+b)(c+d)(a+c)(b+d)} ，其中 n=a+b+c+d ， P(\\chi^2\\ge 3.841)\\approx 0.05 .） ","questionHtml":"某地区为调查初中学生体育锻炼时长与学业成绩的关系，从该地区 29000 名初中生中抽取 580 人，得到日均体育锻炼时长（表中简称时长）与学业成绩的数据如下表所示：<br><br><div class=\"gk-center\"><div class=\"gk-table-scroll\"><table class=\"gk-table\"><tr><td>时长</td><td><span class=\"gk-math\" data-tex=\"[0,0.5)\">[0,0.5)</span></td><td><span class=\"gk-math\" data-tex=\"[0.5,1)\">[0.5,1)</span></td><td><span class=\"gk-math\" data-tex=\"[1,1.5)\">[1,1.5)</span></td><td><span class=\"gk-math\" data-tex=\"[1.5,2)\">[1.5,2)</span></td><td><span class=\"gk-math\" data-tex=\"[2,2.5)\">[2,2.5)</span></td><td>合计</td></tr><tr><td>优秀</td><td>5</td><td>44</td><td>42</td><td>3</td><td>1</td><td>95</td></tr><tr><td>不优秀</td><td>134</td><td>147</td><td>137</td><td>40</td><td>27</td><td>485</td></tr><tr><td>合计</td><td>139</td><td>191</td><td>179</td><td>43</td><td>28</td><td>580</td></tr></table></div></div><br><br><ol class=\"gk-subparts\"><li>估计该地区 29000 名初中生中体育锻炼时长大于 1 小时人数；</li><li>估计该地区初中生平均日均体育锻炼时长（结果精确到 0.1 小时）；</li><li>判断是否有 95% 的把握认为该地区初中生学业成绩优秀与日均体育锻炼时长不小于 1 小时且小于 2 小时有关？ （附：<span class=\"gk-math\" data-tex=\"\\chi^2=\\frac{n(ad-bc)^2}{(a+b)(c+d)(a+c)(b+d)}\">\\chi^2=\\frac{n(ad-bc)^2}{(a+b)(c+d)(a+c)(b+d)}</span>，其中 <span class=\"gk-math\" data-tex=\"n=a+b+c+d\">n=a+b+c+d</span>，<span class=\"gk-math\" data-tex=\"P(\\chi^2\\ge 3.841)\\approx 0.05\">P(\\chi^2\\ge 3.841)\\approx 0.05</span>.）</li></ol>","optionsHtml":[],"answerHtml":"<span>见下方分步解析</span>","answerKey":"","solutionHtml":"<ol class=\"gk-subparts\"><li>锻炼时长大于 1 小时的人数占比为 <span class=\"gk-math\" data-tex=\"\\frac{179+43+28}{580}=\\frac{25}{58}\">\\frac{179+43+28}{580}=\\frac{25}{58}</span>. 故估计该地区 29000 名初中生中体育锻炼时长大于 1 小时的人数约为 <span class=\"gk-math\" data-tex=\"29000\\times \\frac{25}{58}=12500\">29000\\times \\frac{25}{58}=12500</span>.</li><li>各组中值加权平均为 <span class=\"gk-math\" data-tex=\"\\frac{540}{580}\\approx 0.9\">\\frac{540}{580}\\approx 0.9</span>， 所以估计该地区初中生平均日均体育锻炼时长为 0.9 小时.</li><li>由题列联表如下：<br><br><div class=\"gk-table-scroll\"><table class=\"gk-table\"><tr><td>时长</td><td><span class=\"gk-math\" data-tex=\"[1,2)\">[1,2)</span></td><td>其他</td><td>合计</td></tr><tr><td>优秀</td><td><span class=\"gk-math\" data-tex=\"a\">a</span></td><td><span class=\"gk-math\" data-tex=\"b\">b</span></td><td><span class=\"gk-math\" data-tex=\"a+b\">a+b</span></td></tr><tr><td>不优秀</td><td><span class=\"gk-math\" data-tex=\"c\">c</span></td><td><span class=\"gk-math\" data-tex=\"d\">d</span></td><td><span class=\"gk-math\" data-tex=\"c+d\">c+d</span></td></tr><tr><td>合计</td><td><span class=\"gk-math\" data-tex=\"a+c\">a+c</span></td><td><span class=\"gk-math\" data-tex=\"b+d\">b+d</span></td><td><span class=\"gk-math\" data-tex=\"a+b+c+d\">a+b+c+d</span></td></tr></table></div><br><br>提出零假设 <span class=\"gk-math\" data-tex=\"H_0\">H_0</span>：该地区初中生学业成绩优秀与日均体育锻炼时长不少于 1 小时但少于 2 小时无关，其中 <span class=\"gk-math\" data-tex=\"\\alpha=0.05\">\\alpha=0.05</span>.<br><br><div class=\"gk-math display\" data-tex=\"\\chi^2=\\frac{580\\times (45\\times 308-177\\times 50)^2}{95\\times 485\\times 222\\times 358}\\approx 3.976&gt;3.841\">\\chi^2=\\frac{580\\times (45\\times 308-177\\times 50)^2}{95\\times 485\\times 222\\times 358}\\approx 3.976&gt;3.841</div> 故零假设不成立，即有 95% 的把握认为该地区初中生学业成绩优秀与日均体育锻炼时长不小于 1 小时且小于 2 小时有关.</li></ol>","sourceNote":"","specialNote":"","answerAlternatives":[]},{"id":"2024-shanghai-q20","paperId":"2024-shanghai","number":20,"type":"written","score":18,"lessonIds":["e1-3.2","6.3"],"difficulty":"挑战","hint":"先用c²=a²+b²；第二问把等腰三角形按三种可能的相等边分别讨论。","legacy":false,"legacyReason":"","searchText":"已知双曲线 \\Gamma:x^2-\\frac{y^2}{b^2}=1 （ b>0 ），左右顶点分别为 A_1 ， A_2 ，过点 M(-2,0) 的直线 l 交双曲线 \\Gamma 于 P ， Q 两点. 若离心率 e=2 ，求 b 的值； 若 b=\\frac{2\\sqrt{6}}{3} ，点 P 在第一象限， \\triangle MA_2P 为等腰三角形，求点 P 的坐标； 连接 QO （ O 为坐标原点）并延长交双曲线 \\Gamma 于点 R ，若 \\overrightarrow{A_1R}\\cdot\\overrightarrow{A_2P}=1 ，求 b 的取值范围. ","questionHtml":"已知双曲线 <span class=\"gk-math\" data-tex=\"\\Gamma:x^2-\\frac{y^2}{b^2}=1\">\\Gamma:x^2-\\frac{y^2}{b^2}=1</span>（<span class=\"gk-math\" data-tex=\"b&gt;0\">b&gt;0</span>），左右顶点分别为 <span class=\"gk-math\" data-tex=\"A_1\">A_1</span>，<span class=\"gk-math\" data-tex=\"A_2\">A_2</span>，过点 <span class=\"gk-math\" data-tex=\"M(-2,0)\">M(-2,0)</span> 的直线 <span class=\"gk-math\" data-tex=\"l\">l</span> 交双曲线 <span class=\"gk-math\" data-tex=\"\\Gamma\">\\Gamma</span> 于 <span class=\"gk-math\" data-tex=\"P\">P</span>，<span class=\"gk-math\" data-tex=\"Q\">Q</span> 两点.<br><br><ol class=\"gk-subparts\"><li>若离心率 <span class=\"gk-math\" data-tex=\"e=2\">e=2</span>，求 <span class=\"gk-math\" data-tex=\"b\">b</span> 的值；</li><li>若 <span class=\"gk-math\" data-tex=\"b=\\frac{2\\sqrt{6}}{3}\">b=\\frac{2\\sqrt{6}}{3}</span>，点 <span class=\"gk-math\" data-tex=\"P\">P</span> 在第一象限，<span class=\"gk-math\" data-tex=\"\\triangle MA_2P\">\\triangle MA_2P</span> 为等腰三角形，求点 <span class=\"gk-math\" data-tex=\"P\">P</span> 的坐标；</li><li>连接 <span class=\"gk-math\" data-tex=\"QO\">QO</span>（<span class=\"gk-math\" data-tex=\"O\">O</span> 为坐标原点）并延长交双曲线 <span class=\"gk-math\" data-tex=\"\\Gamma\">\\Gamma</span> 于点 <span class=\"gk-math\" data-tex=\"R\">R</span>，若 <span class=\"gk-math\" data-tex=\"\\overrightarrow{A_1R}\\cdot\\overrightarrow{A_2P}=1\">\\overrightarrow{A_1R}\\cdot\\overrightarrow{A_2P}=1</span>，求 <span class=\"gk-math\" data-tex=\"b\">b</span> 的取值范围.</li></ol>","optionsHtml":[],"answerHtml":"<span>见下方分步解析</span>","answerKey":"","solutionHtml":"<ol class=\"gk-subparts\"><li>对于双曲线 <span class=\"gk-math\" data-tex=\"x^2-\\frac{y^2}{b^2}=1\">x^2-\\frac{y^2}{b^2}=1</span>， 有 <span class=\"gk-math\" data-tex=\"a=1\">a=1</span>. 因为 <span class=\"gk-math\" data-tex=\"e=\\frac{c}{a}=2\">e=\\frac{c}{a}=2</span>，所以 <span class=\"gk-math\" data-tex=\"c=2\">c=2</span>. 又 <span class=\"gk-math\" data-tex=\"c^2=a^2+b^2\">c^2=a^2+b^2</span>，故 <span class=\"gk-math\" data-tex=\"b=\\sqrt{c^2-a^2}=\\sqrt{4-1}=\\sqrt{3}\">b=\\sqrt{c^2-a^2}=\\sqrt{4-1}=\\sqrt{3}</span>.</li><li>当 <span class=\"gk-math\" data-tex=\"b=\\frac{2\\sqrt{6}}{3}\">b=\\frac{2\\sqrt{6}}{3}</span> 时，双曲线方程为 <span class=\"gk-math\" data-tex=\"x^2-\\frac{3y^2}{8}=1\">x^2-\\frac{3y^2}{8}=1</span>. 其中 <span class=\"gk-math\" data-tex=\"M(-2,0)\">M(-2,0)</span>，<span class=\"gk-math\" data-tex=\"A_2(1,0)\">A_2(1,0)</span>.<br><br>若以 <span class=\"gk-math\" data-tex=\"MA_2\">MA_2</span> 为底，则点 <span class=\"gk-math\" data-tex=\"P\">P</span> 落在直线 <span class=\"gk-math\" data-tex=\"x=-\\frac{1}{2}\">x=-\\frac{1}{2}</span> 上，与点 <span class=\"gk-math\" data-tex=\"P\">P</span> 在第一象限矛盾，舍去.<br><br>若以 <span class=\"gk-math\" data-tex=\"A_2P\">A_2P</span> 为底，则 <span class=\"gk-math\" data-tex=\"MP=MA_2=3\">MP=MA_2=3</span>. 联立 <div class=\"gk-math display\" data-tex=\"\\begin{cases}\nx^2-\\frac{3y^2}{8}=1,\\\\\n(x+2)^2+y^2=9,\n\\end{cases}\">\\begin{cases}\nx^2-\\frac{3y^2}{8}=1,\\\\\n(x+2)^2+y^2=9,\n\\end{cases}</div> 解得 <span class=\"gk-math\" data-tex=\"\\left( -\\frac{23}{11},\\frac{8\\sqrt{17}}{11} \\right)\">\\left( -\\frac{23}{11},\\frac{8\\sqrt{17}}{11} \\right)</span>，<span class=\"gk-math\" data-tex=\"\\left(-\\frac{23}{11},-\\frac{8\\sqrt{17}}{11}\\right)\">\\left(-\\frac{23}{11},-\\frac{8\\sqrt{17}}{11}\\right)</span>，<span class=\"gk-math\" data-tex=\"(1,0)\">(1,0)</span>. 这些点都不在第一象限，故舍去.<br><br>若以 <span class=\"gk-math\" data-tex=\"MP\">MP</span> 为底，则 <span class=\"gk-math\" data-tex=\"A_2P=MA_2=3\">A_2P=MA_2=3</span>. 设 <span class=\"gk-math\" data-tex=\"P(x_0,y_0)\">P(x_0,y_0)</span>，其中 <span class=\"gk-math\" data-tex=\"x_0&gt;0\">x_0&gt;0</span>，<span class=\"gk-math\" data-tex=\"y_0&gt;0\">y_0&gt;0</span>，则 <div class=\"gk-math display\" data-tex=\"\\begin{cases}\n(x_0-1)^2+y_0^2=9,\\\\\nx_0^2-\\frac{3y_0^2}{8}=1.\n\\end{cases}\">\\begin{cases}\n(x_0-1)^2+y_0^2=9,\\\\\nx_0^2-\\frac{3y_0^2}{8}=1.\n\\end{cases}</div> 解得 <span class=\"gk-math\" data-tex=\"x_0=2\">x_0=2</span>，<span class=\"gk-math\" data-tex=\"y_0=2\\sqrt{2}\">y_0=2\\sqrt{2}</span>. 故 <span class=\"gk-math\" data-tex=\"P(2,2\\sqrt{2})\">P(2,2\\sqrt{2})</span>.</li><li>根据题意，<span class=\"gk-math\" data-tex=\"A_1(-1,0)\">A_1(-1,0)</span>，<span class=\"gk-math\" data-tex=\"A_2(1,0)\">A_2(1,0)</span>. 水平直线 <span class=\"gk-math\" data-tex=\"y=0\">y=0</span> 与双曲线的交点为 <span class=\"gk-math\" data-tex=\"A_1\">A_1</span>，<span class=\"gk-math\" data-tex=\"A_2\">A_2</span>，不满足 <span class=\"gk-math\" data-tex=\"\\overrightarrow{A_1R}\\cdot\\overrightarrow{A_2P}=1\">\\overrightarrow{A_1R}\\cdot\\overrightarrow{A_2P}=1</span>，故设 <span class=\"gk-math\" data-tex=\"l:x=my-2\">l:x=my-2</span>，其中 <span class=\"gk-math\" data-tex=\"m\">m</span> 可为 <span class=\"gk-math\" data-tex=\"0\">0</span>（此时为直线 <span class=\"gk-math\" data-tex=\"x=-2\">x=-2</span>）. 设 <span class=\"gk-math\" data-tex=\"P(x_1,y_1)\">P(x_1,y_1)</span>，<span class=\"gk-math\" data-tex=\"Q(x_2,y_2)\">Q(x_2,y_2)</span>. 由双曲线的对称性知 <span class=\"gk-math\" data-tex=\"R(-x_2,-y_2)\">R(-x_2,-y_2)</span>. 联立 <div class=\"gk-math display\" data-tex=\"\\begin{cases}\nx=my-2,\\\\\nx^2-\\frac{y^2}{b^2}=1\n\\end{cases}\">\\begin{cases}\nx=my-2,\\\\\nx^2-\\frac{y^2}{b^2}=1\n\\end{cases}</div> 可得关于 <span class=\"gk-math\" data-tex=\"y\">y</span> 的方程 <span class=\"gk-math\" data-tex=\"(b^2m^2-1)y^2-4b^2my+3b^2=0\">(b^2m^2-1)y^2-4b^2my+3b^2=0</span>. 因此 <span class=\"gk-math\" data-tex=\"y_1+y_2=\\frac{4b^2m}{b^2m^2-1}\">y_1+y_2=\\frac{4b^2m}{b^2m^2-1}</span>，<span class=\"gk-math\" data-tex=\"y_1y_2=\\frac{3b^2}{b^2m^2-1}\">y_1y_2=\\frac{3b^2}{b^2m^2-1}</span>.<br><br><figure class=\"gk-figure\"><button class=\"gk-zoom\" style=\"width:min(100%,449px)\" data-action=\"zoom-image\" data-label=\"高考题图\" data-src=\"./assets/gaokao/figures/2024/shanghai/q20_solution_fig1.webp\" aria-label=\"放大高考题图\"><img src=\"./assets/gaokao/figures/2024/shanghai/q20_solution_fig1.webp\" alt=\"高考题图，点击可放大\" width=\"433\" height=\"329\" style=\"aspect-ratio:433/329;width:100%\" loading=\"lazy\"></button></figure><br><br>又 <span class=\"gk-math\" data-tex=\"\\overrightarrow{A_1R}=(-x_2+1,-y_2)\">\\overrightarrow{A_1R}=(-x_2+1,-y_2)</span>，<span class=\"gk-math\" data-tex=\"\\overrightarrow{A_2P}=(x_1-1,y_1)\">\\overrightarrow{A_2P}=(x_1-1,y_1)</span>， 由 <span class=\"gk-math\" data-tex=\"\\overrightarrow{A_1R}\\cdot\\overrightarrow{A_2P}=1\">\\overrightarrow{A_1R}\\cdot\\overrightarrow{A_2P}=1</span>，并结合 <span class=\"gk-math\" data-tex=\"x_1=my_1-2\">x_1=my_1-2</span>，<span class=\"gk-math\" data-tex=\"x_2=my_2-2\">x_2=my_2-2</span>，得 <div class=\"gk-math display\" data-tex=\"(-x_2+1)(x_1-1)-y_1y_2=1\n\\iff -(my_2-3)(my_1-3)-y_1y_2=1\">(-x_2+1)(x_1-1)-y_1y_2=1\n\\iff -(my_2-3)(my_1-3)-y_1y_2=1</div> 从而 <div class=\"gk-math display\" data-tex=\"y_1y_2(m^2+1)-3m(y_1+y_2)+10=0\">y_1y_2(m^2+1)-3m(y_1+y_2)+10=0</div> 将 <span class=\"gk-math\" data-tex=\"y_1+y_2=\\frac{4b^2m}{b^2m^2-1}\">y_1+y_2=\\frac{4b^2m}{b^2m^2-1}</span>，<span class=\"gk-math\" data-tex=\"y_1y_2=\\frac{3b^2}{b^2m^2-1}\">y_1y_2=\\frac{3b^2}{b^2m^2-1}</span> 代入上式，得 <div class=\"gk-math display\" data-tex=\"(m^2+1)\\cdot \\frac{3b^2}{b^2m^2-1}-3m\\cdot \\frac{4b^2m}{b^2m^2-1}+10=0\n\\iff b^2m^2+3b^2-10=0\">(m^2+1)\\cdot \\frac{3b^2}{b^2m^2-1}-3m\\cdot \\frac{4b^2m}{b^2m^2-1}+10=0\n\\iff b^2m^2+3b^2-10=0</div> 所以 <span class=\"gk-math\" data-tex=\"m^2=\\frac{10}{b^2}-3\">m^2=\\frac{10}{b^2}-3</span>. 由 <span class=\"gk-math\" data-tex=\"m^2\\ge 0\">m^2\\ge 0</span> 得 <span class=\"gk-math\" data-tex=\"0&lt;b^2\\le\\frac{10}{3}\">0&lt;b^2\\le\\frac{10}{3}</span>. 又由 <span class=\"gk-math\" data-tex=\"b^2m^2-1\\ne 0\">b^2m^2-1\\ne 0</span> 得 <span class=\"gk-math\" data-tex=\"10-3b^2\\ne 1\">10-3b^2\\ne 1</span>， 即 <span class=\"gk-math\" data-tex=\"b^2\\ne 3\">b^2\\ne 3</span>. 故 <span class=\"gk-math\" data-tex=\"b^2\\in \\left( 0,3 \\right)\\cup \\left( 3,\\frac{10}{3} \\right]\">b^2\\in \\left( 0,3 \\right)\\cup \\left( 3,\\frac{10}{3} \\right]</span>. 因为 <span class=\"gk-math\" data-tex=\"b&gt;0\">b&gt;0</span>，所以 <span class=\"gk-math\" data-tex=\"b\\in (0,\\sqrt{3})\\cup \\left( \\sqrt{3},\\frac{\\sqrt{30}}{3} \\right]\">b\\in (0,\\sqrt{3})\\cup \\left( \\sqrt{3},\\frac{\\sqrt{30}}{3} \\right]</span>.</li></ol>","sourceNote":"","specialNote":"","answerAlternatives":[]},{"id":"2024-shanghai-q21","paperId":"2024-shanghai","number":21,"type":"written","score":18,"lessonIds":["e2-5.3","e2-5.1","2.2"],"difficulty":"挑战","hint":"s(x)是距离的平方，求最近点就是求s(x)最小值；第三问把两个“距离最小”不等式相加。","legacy":false,"legacyReason":"","searchText":"设 D 是 \\R 的一个非空子集， y=f(x) 是定义在 D 上的函数. 对于点 M(a,b) ，记 s(x)=(x-a)^2+\\left( f(x)-b \\right)^2 . 若对于点 P(x_0,f(x_0)) ，函数 y=s(x) 在 x=x_0 处取得最小值，则称 P 是 M 的 f 最近点. 对于 f(x)=\\frac{1}{x} ， M(0,0) ， D=(0,+\\infty) ，求证：存在 M 的 f 最近点； 对于 f(x)=\\e^x ， M(1,0) ， D=\\R ，若曲线 y=f(x) 上一点 P 满足 MP 垂直于 y=f(x) 在点 P(x_0,f(x_0)) 处的切线，则 P 是否为 M 的 f 最近点？ 已知 D=\\R ， y=f(x) 的导函数为 y=f'(x) ，且 y=g(x) 在 \\R 上的函数值恒正. 对任意 t\\in \\R ，点 M_1 的坐标为 (t-1,f(t)-g(t)) ，点 M_2 的坐标为 (t+1,f(t)+g(t)) . 若对任意的 t\\in \\R ，总存在 y=f(x) 上一点 P ，使得 P 既是 M_1 的 f 最近点，又是 M_2 的 f 最近点，试求 y=f(x) 的单调性. ","questionHtml":"设 <span class=\"gk-math\" data-tex=\"D\">D</span> 是 <span class=\"gk-math\" data-tex=\"\\R\">\\R</span> 的一个非空子集，<span class=\"gk-math\" data-tex=\"y=f(x)\">y=f(x)</span> 是定义在 <span class=\"gk-math\" data-tex=\"D\">D</span> 上的函数. 对于点 <span class=\"gk-math\" data-tex=\"M(a,b)\">M(a,b)</span>，记 <span class=\"gk-math\" data-tex=\"s(x)=(x-a)^2+\\left( f(x)-b \\right)^2\">s(x)=(x-a)^2+\\left( f(x)-b \\right)^2</span>. 若对于点 <span class=\"gk-math\" data-tex=\"P(x_0,f(x_0))\">P(x_0,f(x_0))</span>，函数 <span class=\"gk-math\" data-tex=\"y=s(x)\">y=s(x)</span> 在 <span class=\"gk-math\" data-tex=\"x=x_0\">x=x_0</span> 处取得最小值，则称 <span class=\"gk-math\" data-tex=\"P\">P</span> 是 <span class=\"gk-math\" data-tex=\"M\">M</span> 的 <span class=\"gk-math\" data-tex=\"f\">f</span> 最近点.<br><br><ol class=\"gk-subparts\"><li>对于 <span class=\"gk-math\" data-tex=\"f(x)=\\frac{1}{x}\">f(x)=\\frac{1}{x}</span>，<span class=\"gk-math\" data-tex=\"M(0,0)\">M(0,0)</span>，<span class=\"gk-math\" data-tex=\"D=(0,+\\infty)\">D=(0,+\\infty)</span>，求证：存在 <span class=\"gk-math\" data-tex=\"M\">M</span> 的 <span class=\"gk-math\" data-tex=\"f\">f</span> 最近点；</li><li>对于 <span class=\"gk-math\" data-tex=\"f(x)=\\e^x\">f(x)=\\e^x</span>，<span class=\"gk-math\" data-tex=\"M(1,0)\">M(1,0)</span>，<span class=\"gk-math\" data-tex=\"D=\\R\">D=\\R</span>，若曲线 <span class=\"gk-math\" data-tex=\"y=f(x)\">y=f(x)</span> 上一点 <span class=\"gk-math\" data-tex=\"P\">P</span> 满足 <span class=\"gk-math\" data-tex=\"MP\">MP</span> 垂直于 <span class=\"gk-math\" data-tex=\"y=f(x)\">y=f(x)</span> 在点 <span class=\"gk-math\" data-tex=\"P(x_0,f(x_0))\">P(x_0,f(x_0))</span> 处的切线，则 <span class=\"gk-math\" data-tex=\"P\">P</span> 是否为 <span class=\"gk-math\" data-tex=\"M\">M</span> 的 <span class=\"gk-math\" data-tex=\"f\">f</span> 最近点？</li><li>已知 <span class=\"gk-math\" data-tex=\"D=\\R\">D=\\R</span>，<span class=\"gk-math\" data-tex=\"y=f(x)\">y=f(x)</span> 的导函数为 <span class=\"gk-math\" data-tex=\"y=f&#x27;(x)\">y=f&#x27;(x)</span>，且 <span class=\"gk-math\" data-tex=\"y=g(x)\">y=g(x)</span> 在 <span class=\"gk-math\" data-tex=\"\\R\">\\R</span> 上的函数值恒正. 对任意 <span class=\"gk-math\" data-tex=\"t\\in \\R\">t\\in \\R</span>，点 <span class=\"gk-math\" data-tex=\"M_1\">M_1</span> 的坐标为 <span class=\"gk-math\" data-tex=\"(t-1,f(t)-g(t))\">(t-1,f(t)-g(t))</span>，点 <span class=\"gk-math\" data-tex=\"M_2\">M_2</span> 的坐标为 <span class=\"gk-math\" data-tex=\"(t+1,f(t)+g(t))\">(t+1,f(t)+g(t))</span>. 若对任意的 <span class=\"gk-math\" data-tex=\"t\\in \\R\">t\\in \\R</span>，总存在 <span class=\"gk-math\" data-tex=\"y=f(x)\">y=f(x)</span> 上一点 <span class=\"gk-math\" data-tex=\"P\">P</span>，使得 <span class=\"gk-math\" data-tex=\"P\">P</span> 既是 <span class=\"gk-math\" data-tex=\"M_1\">M_1</span> 的 <span class=\"gk-math\" data-tex=\"f\">f</span> 最近点，又是 <span class=\"gk-math\" data-tex=\"M_2\">M_2</span> 的 <span class=\"gk-math\" data-tex=\"f\">f</span> 最近点，试求 <span class=\"gk-math\" data-tex=\"y=f(x)\">y=f(x)</span> 的单调性.</li></ol>","optionsHtml":[],"answerHtml":"<span>见下方分步解析</span>","answerKey":"","solutionHtml":"<ol class=\"gk-subparts\"><li>当 <span class=\"gk-math\" data-tex=\"M(0,0)\">M(0,0)</span> 时， <div class=\"gk-math display\" data-tex=\"s(x)=x^2+\\left( \\frac{1}{x} \\right)^2=x^2+\\frac{1}{x^2}\\ge 2\\sqrt{x^2\\cdot \\frac{1}{x^2}}=2\">s(x)=x^2+\\left( \\frac{1}{x} \\right)^2=x^2+\\frac{1}{x^2}\\ge 2\\sqrt{x^2\\cdot \\frac{1}{x^2}}=2</div> 当且仅当 <span class=\"gk-math\" data-tex=\"x^2=\\frac{1}{x^2}\">x^2=\\frac{1}{x^2}</span>， 即 <span class=\"gk-math\" data-tex=\"x=1\">x=1</span> 时取等号. 因此存在点 <span class=\"gk-math\" data-tex=\"P(1,1)\">P(1,1)</span>， 使它是 <span class=\"gk-math\" data-tex=\"M(0,0)\">M(0,0)</span> 在 <span class=\"gk-math\" data-tex=\"f(x)\">f(x)</span> 上的“最近点”.</li><li>由题设， <span class=\"gk-math\" data-tex=\"s(x)=(x-1)^2+\\left( \\e^x-0 \\right)^2=(x-1)^2+\\e^{2x}\">s(x)=(x-1)^2+\\left( \\e^x-0 \\right)^2=(x-1)^2+\\e^{2x}</span>. 则 <span class=\"gk-math\" data-tex=\"s&#x27;(x)=2(x-1)+2\\e^{2x}\">s&#x27;(x)=2(x-1)+2\\e^{2x}</span>. 因为 <span class=\"gk-math\" data-tex=\"2(x-1)\">2(x-1)</span> 与 <span class=\"gk-math\" data-tex=\"2\\e^{2x}\">2\\e^{2x}</span> 都是严格增函数，所以 <span class=\"gk-math\" data-tex=\"s&#x27;(x)\">s&#x27;(x)</span> 也是严格增函数. 又 <span class=\"gk-math\" data-tex=\"s&#x27;(0)=0\">s&#x27;(0)=0</span>， 因此 <span class=\"gk-math\" data-tex=\"x=0\">x=0</span> 为 <span class=\"gk-math\" data-tex=\"s(x)\">s(x)</span> 的最小值点，此时 <span class=\"gk-math\" data-tex=\"P(0,1)\">P(0,1)</span>. 又 <span class=\"gk-math\" data-tex=\"f&#x27;(x)=\\e^x\">f&#x27;(x)=\\e^x</span>， 故 <span class=\"gk-math\" data-tex=\"f(x)\">f(x)</span> 在点 <span class=\"gk-math\" data-tex=\"P\">P</span> 处的切线斜率为 <span class=\"gk-math\" data-tex=\"f&#x27;(0)=1\">f&#x27;(0)=1</span>. 而 <span class=\"gk-math\" data-tex=\"k_{MP}=\\frac{0-1}{1-0}=-1\">k_{MP}=\\frac{0-1}{1-0}=-1</span>， 所以 <span class=\"gk-math\" data-tex=\"k_{MP}\\cdot 1=-1\">k_{MP}\\cdot 1=-1</span>. 因此直线 <span class=\"gk-math\" data-tex=\"MP\">MP</span> 与切线垂直. 故这样的点存在，且 <span class=\"gk-math\" data-tex=\"P(0,1)\">P(0,1)</span>.</li><li>设 <span class=\"gk-math\" data-tex=\"s_1(x)=(x-t+1)^2+\\left( f(x)-f(t)+g(t) \\right)^2\">s_1(x)=(x-t+1)^2+\\left( f(x)-f(t)+g(t) \\right)^2</span>， <span class=\"gk-math\" data-tex=\"s_2(x)=(x-t-1)^2+\\left( f(x)-f(t)-g(t) \\right)^2\">s_2(x)=(x-t-1)^2+\\left( f(x)-f(t)-g(t) \\right)^2</span>. 若点 <span class=\"gk-math\" data-tex=\"P(x_0,f(x_0))\">P(x_0,f(x_0))</span> 同时是 <span class=\"gk-math\" data-tex=\"M_1\">M_1</span>，<span class=\"gk-math\" data-tex=\"M_2\">M_2</span> 的最近点，则 <span class=\"gk-math\" data-tex=\"x_0\">x_0</span> 同时是 <span class=\"gk-math\" data-tex=\"s_1\">s_1</span>，<span class=\"gk-math\" data-tex=\"s_2\">s_2</span> 的最小值点，所以 <span class=\"gk-math\" data-tex=\"s_1&#x27;(x_0)=0\">s_1&#x27;(x_0)=0</span>，<span class=\"gk-math\" data-tex=\"s_2&#x27;(x_0)=0\">s_2&#x27;(x_0)=0</span>. 即 <div class=\"gk-math display\" data-tex=\"\\begin{cases}\n2(x_0-t+1)+2f&#x27;(x_0)\\left( f(x_0)-f(t)+g(t) \\right)=0,\\\\\n2(x_0-t-1)+2f&#x27;(x_0)\\left( f(x_0)-f(t)-g(t) \\right)=0.\n\\end{cases}\">\\begin{cases}\n2(x_0-t+1)+2f&#x27;(x_0)\\left( f(x_0)-f(t)+g(t) \\right)=0,\\\\\n2(x_0-t-1)+2f&#x27;(x_0)\\left( f(x_0)-f(t)-g(t) \\right)=0.\n\\end{cases}</div> 两式相减得 <span class=\"gk-math\" data-tex=\"1+f&#x27;(x_0)g(t)=0\">1+f&#x27;(x_0)g(t)=0</span>， 故 <span class=\"gk-math\" data-tex=\"f&#x27;(x_0)=-\\frac{1}{g(t)}&lt;0\">f&#x27;(x_0)=-\\frac{1}{g(t)}&lt;0</span>. 再由“最近点”定义，有 <span class=\"gk-math\" data-tex=\"s_1(x_0)\\le s_1(t)\">s_1(x_0)\\le s_1(t)</span>，<span class=\"gk-math\" data-tex=\"s_2(x_0)\\le s_2(t)\">s_2(x_0)\\le s_2(t)</span>. 两式相加可得 <span class=\"gk-math\" data-tex=\"(x_0-t)^2+\\left( f(x_0)-f(t) \\right)^2\\le 0\">(x_0-t)^2+\\left( f(x_0)-f(t) \\right)^2\\le 0</span>. 因此 <span class=\"gk-math\" data-tex=\"x_0=t\">x_0=t</span>，<span class=\"gk-math\" data-tex=\"f(x_0)=f(t)\">f(x_0)=f(t)</span>. 于是 <span class=\"gk-math\" data-tex=\"f&#x27;(t)=f&#x27;(x_0)=-\\frac{1}{g(t)}&lt;0\">f&#x27;(t)=f&#x27;(x_0)=-\\frac{1}{g(t)}&lt;0</span>. 由于 <span class=\"gk-math\" data-tex=\"t\\in \\R\">t\\in \\R</span> 任意，故 <span class=\"gk-math\" data-tex=\"f&#x27;(t)&lt;0\">f&#x27;(t)&lt;0</span>，<span class=\"gk-math\" data-tex=\"\\text{对任意 }t\\in \\R\\text{ 都成立}\">\\text{对任意 }t\\in \\R\\text{ 都成立}</span>. 所以 <span class=\"gk-math\" data-tex=\"f(x)\">f(x)</span> 在 <span class=\"gk-math\" data-tex=\"\\R\">\\R</span> 上严格单调递减.</li></ol>","sourceNote":"","specialNote":"","answerAlternatives":[]}];
